const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(id,w=900)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const pics={run:photo('photo-1552674605-db6ffd4facb5'),bike:photo('photo-1541625602330-2277b4c46182'),hike:photo('photo-1551632811-561732d1e306'),yoga:photo('photo-1544367567-0f2fcb009e0b'),anna:photo('photo-1534528741775-53994a69daeb',500),max:photo('photo-1500648767791-00dcc994a43e',500),ira:photo('photo-1524504388940-b1c1722653e1',500),alex:photo('photo-1506794778202-cad84cf45f1d',500)};
const seed=[{id:1,title:'Вечерний easy run',cat:'Бег',date:'2026-10-29',time:'19:00',place:'Парк Победы',distance:'≈ 1,2 км',level:'Любой уровень',spec:'5 км · темп 6:30–7:00',count:8,limit:15,price:0,img:pics.run,official:true,host:'Dixon Running Club'},{id:2,title:'На двух колёсах за город',cat:'Велосипед',date:'2026-10-31',time:'10:00',place:'Велодорожка, Дрозды',distance:'≈ 3 км',level:'Средний',spec:'35 км · 20–25 км/ч',count:6,limit:12,price:0,img:pics.bike,host:'Максим'},{id:3,title:'Выходные на тропе',cat:'Outdoor',date:'2026-11-01',time:'09:00',place:'Раубичи, точка сбора',distance:'≈ 22 км',level:'Начинающий',spec:'12 км · 3 часа · удобная обувь',count:9,limit:16,price:0,img:pics.hike,host:'Active Minsk'},{id:4,title:'Перезагрузка: yoga flow',cat:'Йога',date:'2026-10-30',time:'18:30',place:'Студия на Октябрьской',distance:'≈ 2 км',level:'Любой уровень',spec:'60 минут · коврик с собой',count:5,limit:10,price:20,img:pics.yoga,host:'Ирина'}];
let state;try{state=JSON.parse(localStorage.getItem('dixon-v1'))}catch{}state=Object.assign({profile:null,events:seed,joined:[],saved:[],liked:[],skipped:[],blocked:[],reports:[],analytics:[],expires:0,clubs:false,matches:[],notifications:[]},state||{});let page='home',filter='Все',feedTab='Все',mode='Спорт',candidate=0;let focusBefore;
const people=[{id:1,name:'Анна',age:27,img:pics.anna,bio:'Бегаю ради хорошего настроения. Ищу компанию на лёгкие пробежки и кофе после.',sport:'Бег · Outdoor',mode:'Спорт',distance:'1–3 км'},{id:2,name:'Максим',age:31,img:pics.max,bio:'Велосипед, падел и спонтанные планы на выходные. Присоединяйся!',sport:'Велосипед · Падел',mode:'Друзья',distance:'3–5 км'},{id:3,name:'Ирина',age:28,img:pics.ira,bio:'Горы зовут. А пока — йога и прогулки по городу.',sport:'Йога · Outdoor',mode:'Дейтинг',distance:'1–3 км'},{id:4,name:'Алексей',age:30,img:pics.alex,bio:'Создаю проекты, бегаю по утрам. Буду рад новым идеям и людям.',sport:'Бег · Зал',mode:'Нетворкинг',distance:'3–5 км'}];
function persist(){try{localStorage.setItem('dixon-v1',JSON.stringify(state))}catch{toast('Хранилище браузера недоступно')}}function track(name,properties={}){state.analytics.push({event_id:crypto.randomUUID(),name,properties,at:new Date().toISOString()});state.analytics=state.analytics.slice(-500);persist()}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}function sheet(s){focusBefore=document.activeElement;$('#sheet').innerHTML='<button class="close" aria-label="Закрыть" onclick="closeSheet()">×</button>'+s;$('#overlay').classList.add('open');document.body.style.overflow='hidden';$('#sheet .close').focus()}function closeSheet(){$('#overlay').classList.remove('open');document.body.style.overflow='';focusBefore?.focus()}document.addEventListener('keydown',e=>{if(!$('#overlay').classList.contains('open'))return;if(e.key==='Escape')closeSheet();if(e.key==='Tab'){const a=[...$('#sheet').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const navs=[['map','◎','Карта'],['find','◇','Найти'],['create','＋','Создать'],['activities','▤','Активности'],['profile','♙','Профиль']];function navigation(){for(const id of ['sideNav','bottomNav'])$('#'+id).innerHTML=navs.map(([p,i,l])=>`<button class="${page===p||(page==='home'&&p==='activities')?'active':''}" onclick="go('${p}')"><span class="nav-icon">${i}</span>${l}</button>`).join('')}
function go(p){page=p;navigation();if(p==='home')home();if(p==='activities')activities();if(p==='map'){track('map_opened');mapPage()}if(p==='find')find();if(p==='create')create();if(p==='profile')profile();window.scrollTo(0,0)}function pageHeader(title,sub='Встречаемся в реальной жизни'){return `<div class="topline"><div><p>${sub}</p><h1>${title}</h1></div><button class="status" onclick="statusSheet()"><span class="dot" style="background:${state.expires>Date.now()?'#36a777':'#aaa'}"></span>${state.expires>Date.now()?'Открыт к общению':'Я открыт к общению'} ↗</button></div>`}function stack(){return `<span class="stack"><img src="${pics.anna}" alt=""><img src="${pics.max}" alt=""><img src="${pics.ira}" alt=""></span>`}function dateLabel(e){return e.date==='2026-10-29'?'СЕГОДНЯ':e.date==='2026-10-30'?'ЗАВТРА':new Date(e.date+'T12:00:00').toLocaleDateString('ru',{day:'numeric',month:'short'}).toUpperCase()}function card(e){return `<article class="event" tabindex="0" role="button" aria-label="${esc(e.title)}" onclick="eventDetail(${e.id})" onkeydown="if(event.key==='Enter')eventDetail(${e.id})"><div class="event-photo"><img src="${e.img}" alt="${esc(e.cat)}" loading="lazy"><span class="badge ${e.official?'official':''}">${e.official?'DIXON OFFICIAL ↗':esc(e.cat)}</span><button class="save" aria-label="Сохранить" onclick="event.stopPropagation();saveEvent(${e.id})">${state.saved.includes(e.id)?'♥':'♡'}</button></div><div class="event-body"><div class="event-time">${dateLabel(e)} · ${esc(e.time)}</div><h3>${esc(e.title)}</h3><p>⌖ ${esc(e.place)} · ${esc(e.distance||'Минск')}</p><p>${esc(e.spec||e.level)}</p><div class="event-foot"><span>${stack()} ${e.count}/${e.limit}</span><span class="free">${e.price?e.price+' BYN':'Бесплатно'} ↗</span></div></div></article>`}function filterChips(){return `<div class="chips">${['Все','Бег','Велосипед','Outdoor','Йога'].map(x=>`<button class="chip ${filter===x?'selected':''}" onclick="filter='${x}';${page==='home'?'home':'activities'}()">${x==='Бег'?'↗ ':x==='Велосипед'?'♧ ':x==='Outdoor'?'△ ':''}${x}</button>`).join('')}</div>`}function eventList(){let a=state.events.filter(e=>filter==='Все'||e.cat===filter);if(feedTab==='Мои')a=a.filter(e=>state.joined.includes(e.id)||e.mine);if(feedTab==='Сохранённые')a=a.filter(e=>state.saved.includes(e.id));if(feedTab==='Сегодня')a=a.filter(e=>e.date==='2026-10-29');return a.length?`<div class="events">${a.map(card).join('')}</div>`:`<div class="empty"><h2>Здесь начинается твоя компания</h2><p>Пока нет подходящих активностей.<br>Собери людей на свою.</p><button class="btn" onclick="go('create')">Создать активность →</button></div>`}
function mapArt(big=false){return `<div class="${big?'bigmap':'map-preview'}"><div class="map-art"></div><div class="river"></div><div class="park"></div><span class="map-name">МИНСК</span>${[['20%','25%',1],['63%','18%',2],['40%','65%',3],['75%','65%',4]].map(([l,t,i])=>`<button class="pin" style="left:${l};top:${t}" aria-label="Открыть активность" onclick="eventDetail(${i})">${['','↗','♧','△','◎'][i]}</button>`).join('')}${!state.blocked.includes(1)?`<button class="pin" style="left:51%;top:40%" aria-label="Анна, приблизительная область" onclick="personDetail(1)"><img src="${pics.anna}" alt="Анна"></button>`:''}${big?'<div class="map-warning">Схема города · демо. Люди показаны приблизительно.</div>':'<button class="map-go" onclick="go(\'map\')">Люди и активности рядом <span>Развернуть ↗</span></button>'}</div>`}function right(){return `<aside class="right-column"><div><div class="right-head">Город в движении <span class="red-text">↗</span></div>${mapArt()}<div class="section-head"><b>Твои люди рядом</b><button onclick="go('find')">Все ↗</button></div><div class="people">${people.filter(p=>!state.blocked.includes(p.id)).slice(0,4).map(p=>`<button class="person-mini" onclick="personDetail(${p.id})"><img src="${p.img}" alt="${p.name}">${p.name}</button>`).join('')}</div></div><div><div class="club"><div class="label">СИЛЬНЕЕ ВМЕСТЕ</div><span class="club-symbol">↗</span><h3>DIXON<br>RUNNING CLUB</h3><p>Неважно, какой у тебя темп.<br>Важно, что мы бежим вместе.</p><button onclick="club()">Открыть клуб ↗</button></div><p class="footer-note">Демонстрация сообщества. Люди, события и числа вымышлены. Дата сценария: 29.10.2026.</p></div></aside>`}
function home(){$('#main').innerHTML=pageHeader('Свои люди. В движении.','Четверг, 29 октября · Минск')+`<section class="hero"><img src="${pics.run}" alt="Беговое сообщество"><div class="hero-index">01 / COMMUNITY FIRST</div><div class="hero-copy"><span class="label">ВЫХОДИ В ГОРОД. НАХОДИ СВОИХ.</span><h2>ХОРОШИЕ ПЛАНЫ<br>НАЧИНАЮТСЯ<br>С ЛЮДЕЙ.</h2><p>Пробежка, новый маршрут или просто кофе после.<br>Твоя компания уже где-то рядом.</p><button class="btn" onclick="go('find')">Найти своих <span style="margin-left:25px">↗</span></button></div><div class="hero-caption">${stack()}<span>Объединяемся через движение</span></div></section><div class="content-grid"><section><div class="section-head"><h2>Есть план <small>на ближайшие дни</small></h2><button onclick="go('activities')">Все активности ↗</button></div>${filterChips()}${eventList()}</section>${right()}</div>`}function activities(){$('#main').innerHTML=pageHeader('Есть план. Присоединяйся.')+`<div class="chips">${['Все','Сегодня','Мои','Сохранённые'].map(t=>`<button class="chip ${feedTab===t?'red':''}" onclick="feedTab='${t}';activities()">${t}</button>`).join('')}</div>${filterChips()}<div class="content-grid"><section>${eventList()}</section>${right()}</div>`}
function mapPage(){$('#main').innerHTML=pageHeader('Твой город в движении.')+`<p class="subtle">Схематическая демо-карта. Нажми на маркер, чтобы открыть активность или профиль.</p>${mapArt(true)}<div class="section-head" style="margin-top:28px"><h2>Ближайшие активности</h2></div><div class="events">${state.events.slice(0,2).map(card).join('')}</div>`}
function eventDetail(id){const e=state.events.find(x=>x.id===id);if(!e)return;track('event_viewed',{id});sheet(`<img class="cover" src="${e.img}" alt="${esc(e.cat)}"><span class="event-time">${dateLabel(e)} · ${esc(e.time)}</span><h2>${esc(e.title)}</h2><p>Организатор: ${esc(e.host)} ${e.official?'✓':''}</p><div class="facts"><div><small>ГДЕ</small>${esc(e.place)}</div><div><small>УРОВЕНЬ</small>${esc(e.level)}</div><div><small>ПАРАМЕТРЫ</small>${esc(e.spec||'Без дополнительных требований')}</div><div><small>УЧАСТНИКИ</small>${e.count} из ${e.limit}</div></div><p>${esc(e.desc||'Знакомимся, двигаемся в комфортном темпе и хорошо проводим время. Приходи за 10 минут до старта. Встречаемся в публичном месте.')}</p><button class="text" onclick="participants(${id})">${stack()} Посмотреть участников ↗</button><div class="actions"><button class="btn" onclick="joinEvent(${id})" ${!state.joined.includes(id)&&e.count>=e.limit?'disabled':''}>${state.joined.includes(id)?'Выйти из активности':e.count>=e.limit?'Мест больше нет':'Присоединиться →'}</button><button class="btn alt" onclick="shareEvent(${id})">Поделиться</button><button class="text" onclick="report('event',${id})">Пожаловаться</button></div><p class="subtle">Демо: участие сохраняется только в этом браузере.</p>`)}function joinEvent(id){if(!state.profile){closeSheet();onboarding();return}let e=state.events.find(x=>x.id===id);if(state.joined.includes(id)){state.joined=state.joined.filter(x=>x!==id);e.count=Math.max(0,e.count-1);track('event_left',{id})}else{if(e.count>=e.limit)return toast('Мест больше нет');state.joined.push(id);e.count++;state.notifications.push('Вы записались: '+e.title);track('event_joined',{id})}persist();eventDetail(id)}function participants(id){sheet('<h2>Участники активности</h2><p>Демонстрационные профили</p>'+people.filter(p=>!state.blocked.includes(p.id)).map(p=>`<button class="report-row" style="display:block;width:100%;text-align:left" onclick="personDetail(${p.id})"><img src="${p.img}" style="width:40px;height:40px;object-fit:cover;border-radius:50%;vertical-align:middle;margin-right:12px" alt="">${p.name}, ${p.age} ↗</button>`).join(''))}function saveEvent(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();toast(state.saved.includes(id)?'Сохранено':'Удалено из сохранённых');go(page)}async function shareEvent(id){track('event_shared',{id});const e=state.events.find(x=>x.id===id);const url=location.origin+location.pathname+'#event-'+id;try{if(navigator.share)await navigator.share({title:e.title,url});else{await navigator.clipboard.writeText(url);toast('Ссылка скопирована')}}catch{toast('Не удалось поделиться. Ссылка: '+url)}}
function find(){const a=people.filter(p=>!state.blocked.includes(p.id)&&!state.liked.includes(p.id)&&!state.skipped.includes(p.id)&&(mode==='Все'||p.mode===mode));const p=a[0];$('#main').innerHTML=pageHeader('Найди свой ритм.')+`<div class="chips">${['Спорт','Друзья','Дейтинг','Нетворкинг','Все'].map(x=>`<button class="chip ${mode===x?'selected':''}" onclick="mode='${x}';find()">${x}</button>`).join('')}</div><p class="subtle">Демо-кандидаты · Минск · приблизительное расстояние</p>`+(mode==='Дейтинг'&&!state.profile?.dating?`<div class="empty"><h2>Знакомства — по твоему выбору</h2><p>Дейтинг включается отдельно в профиле.<br>Доступен только с 18 лет.</p><button class="btn" onclick="onboarding()">Настроить профиль →</button></div>`:p?`<article class="person-card" id="swipeCard"><img src="${p.img}" alt="${p.name}"><div class="info"><h2>${p.name}, ${p.age}</h2><span class="subtle">Минск · ${p.distance}</span><p>${p.bio}</p><span class="chip">${p.sport}</span><div class="swipe-actions"><button class="btn alt" onclick="swipe(${p.id},false)">× Пропустить</button><button class="btn" onclick="swipe(${p.id},true)">♥ Нравится</button></div><button class="text" style="color:#aaa;margin-top:14px" onclick="personDetail(${p.id})">Профиль и безопасность ↗</button></div></article>`:`<div class="empty"><h2>Новые люди ещё впереди</h2><p>А пока познакомься через совместную активность.</p><button class="btn" onclick="go('activities')">Найти активность →</button><button class="text" style="margin:15px auto" onclick="state.liked=[];state.skipped=[];persist();find()">Сбросить демо-свайпы</button></div>`);const c=$('#swipeCard');if(c){let x=0;c.addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});c.addEventListener('touchend',e=>{let d=e.changedTouches[0].clientX-x;if(Math.abs(d)>80)swipe(p.id,d>0)},{passive:true})}}
function swipe(id,like){if(!state.profile)return onboarding();(like?state.liked:state.skipped).push(id);track(like?'swipe_right':'swipe_left',{id});find();if(like){state.matches.push(id);track('match_created',{id,demo:true});const p=people.find(x=>x.id===id);sheet(`<span class="event-time">ДЕМО ВЗАИМНОГО ЛАЙКА</span><h2>Вы в одном ритме.</h2><img src="${p.img}" alt="${p.name}" style="height:160px;width:160px;object-fit:cover;border-radius:50%"><p>${p.name} тоже хочет познакомиться. В этой демонстрации встречный лайк задан сценарием.</p><div class="actions"><button class="btn" onclick="closeSheet();go('activities')">Позвать на активность →</button><button class="btn alt" onclick="toast('У демо-профиля нет реального Telegram-контакта')">Написать</button></div>`)}persist()}
function personDetail(id){const p=people.find(x=>x.id===id);if(!p||state.blocked.includes(id))return;track('profile_viewed',{id});sheet(`<img class="cover" src="${p.img}" alt="${p.name}"><h2>${p.name}, ${p.age}</h2><p>Минск · ${p.distance}<br>${p.bio}</p><span class="chip">${p.sport}</span><p class="subtle">Вымышленный профиль. Точные координаты и контакты скрыты.</p><div class="actions"><button class="btn" onclick="closeSheet();swipe(${id},true)">♥ Нравится</button><button class="text" onclick="report('user',${id})">Пожаловаться</button><button class="text red-text" onclick="block(${id})">Заблокировать</button></div>`)}function block(id){state.blocked.push(id);state.matches=state.matches.filter(x=>x!==id);persist();closeSheet();go(page);toast('Пользователь скрыт в этой демонстрации')}
function create(){$('#main').innerHTML=pageHeader('Собери свою компанию.')+`<p class="subtle">Не жди идеального плана. Предложи свой.</p><form class="form" id="createForm"><label for="title">Что будем делать?</label><input id="title" name="title" required maxlength="90" placeholder="Например, лёгкая пробежка и кофе"><div class="row"><div><label for="category">Активность</label><select id="category" name="cat" onchange="sportFields()"><option>Бег</option><option>Велосипед</option><option>Outdoor</option><option>Йога</option><option>Падел</option><option>Другое</option></select></div><div><label for="level">Уровень</label><select id="level" name="level"><option>Любой уровень</option><option>Начинающий</option><option>Средний</option><option>Продвинутый</option></select></div></div><div class="row"><div><label for="date">Дата</label><input id="date" name="date" type="date" min="2026-10-29" value="2026-10-30" required></div><div><label for="time">Время · Минск</label><input id="time" name="time" type="time" value="19:00" required></div></div><label for="place">Публичное место встречи</label><input id="place" name="place" required placeholder="Парк, вход или общественная площадка" maxlength="150"><div id="sportFields"></div><div class="row"><div><label for="limit">Лимит участников</label><input id="limit" name="limit" type="number" min="2" max="100" value="10" required></div><div><label for="price">Стоимость · BYN</label><input id="price" name="price" type="number" min="0" max="10000" value="0" required></div></div><label for="desc">Что нужно знать участникам?</label><textarea id="desc" name="desc" maxlength="1500" placeholder="Темп, снаряжение, как найти друг друга"></textarea><button class="btn" type="submit">Предпросмотр активности →</button></form>`;sportFields();$('#createForm').onsubmit=e=>{e.preventDefault();if(!state.profile)return onboarding();const d=Object.fromEntries(new FormData(e.target));const draft={...d,id:Date.now(),limit:+d.limit,price:+d.price,count:1,mine:true,host:state.profile.name,img:d.cat==='Велосипед'?pics.bike:d.cat==='Outdoor'?pics.hike:d.cat==='Йога'?pics.yoga:pics.run,distance:'Минск',spec:d.specific||d.level};window.draft=draft;sheet(`<span class="label">ПРЕДПРОСМОТР</span><h2>${esc(draft.title)}</h2><p>${esc(draft.date)} · ${esc(draft.time)}<br>${esc(draft.place)}<br>${esc(draft.spec)}<br>До ${draft.limit} человек · ${draft.price?draft.price+' BYN':'Бесплатно'}</p><p>${esc(draft.desc)}</p><button class="btn" onclick="publishDraft()">Создать в демо →</button>`)}}
function sportFields(){const cat=$('#category').value;const hints={'Бег':'5 км · темп 6:30 · асфальт','Велосипед':'30 км · 22 км/ч · шоссейный велосипед','Outdoor':'12 км · набор 200 м · 3 часа · треккинговая обувь','Йога':'60 минут · коврик с собой','Падел':'90 минут · ракетки доступны'};$('#sportFields').innerHTML=`<label for="specific">Спортивные параметры</label><input id="specific" name="specific" maxlength="200" placeholder="${hints[cat]||'Формат и необходимые вещи'}">`}
function publishDraft(){state.events.unshift(window.draft);state.joined.push(window.draft.id);track('event_created',{id:window.draft.id});persist();closeSheet();go('activities');toast('Активность создана локально')}
function onboarding(){track('onboarding_started');const p=state.profile||{};sheet(`<span class="event-time">ТВОЙ ПРОФИЛЬ · ОКОЛО МИНУТЫ</span><h2>Начнём с тебя.</h2><form class="form" id="onboard"><label for="name">Имя</label><input name="name" id="name" required maxlength="50" value="${esc(p.name||'')}" placeholder="Как тебя зовут?"><div class="row"><div><label for="birth">Дата рождения · 18+</label><input id="birth" name="birth" type="date" required max="2008-10-29" value="${esc(p.birth||'')}"></div><div><label for="gender">Пол · необязательно</label><select id="gender" name="gender"><option>Не указывать</option><option>Женский</option><option>Мужской</option><option>Другое</option></select></div></div><label for="bio">О себе</label><textarea id="bio" name="bio" maxlength="300" placeholder="Как любишь проводить время?">${esc(p.bio||'')}</textarea><label>Что тебе интересно?</label><div class="choices">${['Бег','Велосипед','Зал','Падел','Йога','Outdoor'].map(s=>`<label style="font-weight:normal;margin:4px"><input style="width:auto;min-height:0" type="checkbox" name="sports" value="${s}" ${(p.sports||[]).includes(s)?'checked':''}> ${s}</label>`).join('')}</div><label>Твои цели</label><div class="choices">${['Спорт','Друзья','Дейтинг','Нетворкинг','Outdoor','Мероприятия','Открыт ко всему'].map(s=>`<label style="font-weight:normal;margin:4px"><input style="width:auto;min-height:0" type="checkbox" name="goals" value="${s}" ${(p.goals||[]).includes(s)?'checked':''}> ${s}</label>`).join('')}</div><label><input type="checkbox" name="consent" required style="width:auto;min-height:0"> Мне 18+, я принимаю правила сообщества</label><p class="subtle">Город: Минск. Геолокация и контакты скрыты по умолчанию. Вводи только тестовые данные: это локальная демонстрация без Telegram-авторизации.</p><button class="btn" type="submit">Сохранить профиль →</button></form>`);$('#onboard').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const birth=String(f.get('birth'));if(birth>'2008-10-29'||birth<'1900-01-01')return toast('Доступно для пользователей от 18 лет');state.profile={name:f.get('name').trim(),birth,bio:f.get('bio'),gender:f.get('gender'),sports:f.getAll('sports'),goals:f.getAll('goals'),dating:f.getAll('goals').includes('Дейтинг')};if(!state.profile.name)return toast('Укажи имя');track('onboarding_completed');persist();closeSheet();go(page);toast('Профиль сохранён в браузере')}}
function profile(){const p=state.profile;$('#main').innerHTML=pageHeader('Твой профиль.')+(p?`<div class="profile-head"><div class="avatar" style="display:grid;place-items:center">${esc(p.name[0])}</div><div><h2>${esc(p.name)}</h2><span class="subtle">Минск · Демо-профиль</span></div></div><p class="subtle">${esc(p.bio||'Движение начинается с тебя.')}</p><div class="chips">${p.sports.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><div class="settings"><button onclick="onboarding()">Редактировать профиль <span>↗</span></button><button onclick="statusSheet()">Видимость на карте <span>${state.expires>Date.now()?'Включена':'Скрыт'}</span></button><button onclick="feedTab='Мои';go('activities')">Мои активности <span>${state.joined.length} ↗</span></button><button onclick="matches()">Мои мэтчи <span>${state.matches.length} ↗</span></button><button onclick="club()">Мой клуб <span>${state.clubs?'Dixon Running Club':'Присоединиться'} ↗</span></button><button onclick="guidelines()">Правила и приватность <span>↗</span></button><button onclick="exportAnalytics()">Выгрузить демо-аналитику <span>↓</span></button><button onclick="deleteProfile()" class="red-text">Удалить локальный профиль <span>×</span></button></div>`:`<div class="empty"><h2>Здесь начинается твоя история</h2><p>Расскажи немного о себе,<br>чтобы находить близких по духу людей.</p><button class="btn" onclick="onboarding()">Создать демо-профиль →</button></div>`)}
function statusSheet(){if(!state.profile)return onboarding();sheet(`<h2>Открыт к общению</h2><p>Ты контролируешь видимость. В демо реальные координаты не запрашиваются и не передаются.</p><form class="form" id="statusForm"><label for="statusType">Что хочется?</label><select id="statusType" name="type">${['Хочу спорт','Хочу компанию','Открыт к знакомствам','Хочу куда-нибудь сегодня','Открыт ко всему'].map(x=>'<option>'+x+'</option>').join('')}</select><label for="ttl">Как долго?</label><select id="ttl" name="ttl"><option value="1">1 час</option><option value="3">3 часа</option><option value="day">До конца дня</option></select><label for="audience">Кто видит?</label><select id="audience" name="audience"><option>Участники сообщества</option><option>Только мои мэтчи</option></select><label><input type="checkbox" name="distance" style="width:auto;min-height:0"> Показывать примерное расстояние</label><button class="btn">Включить демо-статус</button></form><button class="text red-text" onclick="state.expires=0;persist();closeSheet();go(page);toast('Видимость выключена')">Скрыть себя сейчас</button>`);$('#statusForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.expires=f.get('ttl')==='day'?Date.parse('2026-10-30T00:00:00+03:00'):Date.now()+Number(f.get('ttl'))*3600000;state.audience=f.get('audience');state.showDistance=f.has('distance');track('location_enabled',{demo:true});persist();closeSheet();go(page)}}
function club(){sheet(`<span class="event-time">OFFICIAL COMMUNITY · ДЕМО</span><h2>DIXON<br>RUNNING CLUB</h2><p>Любой темп. Общий маршрут.<br>Регулярные пробежки, новые люди и кофе после финиша.</p><div class="facts"><div><small>ГОРОД</small>Минск</div><div><small>РИТМ</small>Пн · Ср · Вс</div></div><p>Правила: уважать темп каждого, не оставлять новичков одних, согласовывать фотографии и выбирать публичные места.</p><button class="btn" onclick="state.clubs=!state.clubs;track('club_joined',{joined:state.clubs,demo:true});persist();club()">${state.clubs?'Выйти из клуба':'Вступить в демо-клуб →'}</button>`)}function matches(){sheet('<h2>Твои мэтчи</h2>'+ (state.matches.filter(id=>!state.blocked.includes(id)).map(id=>{const p=people.find(x=>x.id===id);return `<div class="report-row"><b>${p.name}</b><p>Демо взаимного лайка</p><button class="btn" onclick="closeSheet();go('activities')">Позвать на активность</button></div>`}).join('')||'<p>Пока нет мэтчей. Найди людей с общими интересами.</p>'))}function notifications(){sheet('<h2>Уведомления</h2><p class="subtle">Локальные уведомления демо. Telegram-бот не подключён.</p>'+ (state.notifications.map(n=>'<div class="report-row">'+esc(n)+'</div>').join('')||'<p>Пока тихо. Самое время выбрать активность.</p>'))}
function report(type,id){sheet(`<h2>Сообщить о проблеме</h2><p>Демонстрация жалобы. Заявка сохранится локально; реальная служба модерации не подключена.</p><form class="form" id="reportForm"><label for="reason">Причина</label><select id="reason" name="reason"><option>Спам</option><option>Домогательства</option><option>Опасное поведение</option><option>Неподходящий контент</option><option>Другое</option></select><label for="details">Комментарий</label><textarea id="details" name="details" maxlength="1000"></textarea><button class="btn">Сохранить демо-жалобу</button></form>`);$('#reportForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.reports.push({id:Date.now(),type,target:id,reason:f.get('reason'),details:f.get('details'),status:'Новая'});persist();closeSheet();toast('Демо-жалоба в локальной очереди')}}function admin(){sheet('<span class="event-time">ДЕМО ИНТЕРФЕЙСА · НЕ ЗАЩИЩЁННАЯ АДМИНКА</span><h2>Модерация</h2><p>В production доступ требует серверного RBAC. Здесь показаны только локальные тестовые жалобы.</p>'+ (state.reports.map(r=>`<div class="report-row"><b>#${r.id} · ${esc(r.reason)}</b><p>${esc(r.type)} ${r.target} · ${esc(r.details)}<br>Статус: ${r.status}</p><button class="btn alt" onclick="resolveReport(${r.id})">Отметить обработанной</button></div>`).join('')||'<p>В локальной очереди нет жалоб.</p>'))}function resolveReport(id){state.reports.find(x=>x.id===id).status='Обработана';persist();admin()}function guidelines(){sheet('<h2>Хорошая компания начинается с уважения.</h2><p>Уважай границы и согласие. Никаких домогательств, дискриминации и спама. Первые встречи — в публичных местах. Не публикуй чужие контакты, фотографии и геолокацию без согласия.</p><h3>Ты контролируешь видимость</h3><p>Геолокация по умолчанию скрыта. Статус действует ограниченное время. Dating включается отдельно с 18 лет. Контакты требуют согласия; блокировка скрывает демо-пользователя.</p><h3>О демонстрации</h3><p>Все действия сохраняются только в localStorage этого браузера. Telegram-авторизация, серверная модерация, настоящий обмен сообщениями и геокарта не подключены. Не вводи реальные личные данные. Удаление локального профиля очищает данные демо.</p>')}function deleteProfile(){sheet('<h2>Удалить данные демо?</h2><p>Профиль, записи, свайпы, жалобы и локальная аналитика будут удалены из этого браузера.</p><button class="btn" onclick="localStorage.removeItem(\'dixon-v1\');location.reload()">Удалить всё</button>')}function cityInfo(){sheet('<h2>Начинаем с Минска.</h2><p>Один город. Живое сообщество.<br>Сейчас открыт демонстрационный пилот. Другие города появятся после проверки спроса и наполнения реальными активностями.</p>')}function exportAnalytics(){const blob=new Blob([JSON.stringify(state.analytics,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='dixon-demo-analytics.json';a.click();URL.revokeObjectURL(u)}
try{const tg=window.Telegram?.WebApp;if(tg?.initData){tg.ready();tg.expand();tg.setHeaderColor('#ffffff');/* Never authenticate from initDataUnsafe. Backend validation required. */}}catch{}track('app_open',{demo:true});go('home');if(location.hash.startsWith('#event-'))eventDetail(Number(location.hash.slice(7)));setInterval(()=>{if(state.expires&&state.expires<=Date.now()){state.expires=0;persist();if(!$('#overlay').classList.contains('open'))go(page)}},30000);
